// th15_s6_b5: TH15 v1.00b Stage 6 Boss3 nonspell. Source st06bs.ecl.txt:302-378.
// Card frame 0 is the shell start; the boss is created after OPENING_BUFFER and the
// source timerReset (st06bs:318) is reconstructed 4 entry frames later (st06bs:311/313).

const TIME_LIMIT: int = 2944;
const OPENING_BUFFER: int = 120;
const PHASE_FRAMES: int = TIME_LIMIT - OPENING_BUFFER - 4;
const TH15_BALL: int = 416;

// st06bs:380-410 Boss3_at(A=volleys, B=ways): random-base rings, volleys 10 frames apart.
sub boss3_at(volleys: int, ways: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL, 6);        // st06bs:385 etSprite(0,4,6)
    sh_ring(0, 1);                     // st06bs:384 etAim(0,3)
    sh_aim(0, 0);
    sh_count(0, ways, 1);              // st06bs:386 etCount(0,$B,1)
    sh_speed(0, 2fx, 0fx);             // st06bs:388; single layer uses first endpoint 2.0
    var base: int = rand(65536);       // st06bs:391 RANDRAD
    var half: int = 32768 / ways;      // st06bs:392,403 E/2 in BAM
    var c: int = -1;                   // st06bs:393
    for f in 0..volleys {              // st06bs:394,408 ($F-- loop)
        c = c + 1;
        sh_angle(0, base as angle, 0deg);  // st06bs:398
        if c < 3 {
            base = rand(65536);        // st06bs:400 fresh RANDRAD
        } else {
            base = base + half;        // st06bs:403
        }
        sh_fire(0);                    // st06bs:405
        wait(10);                      // st06bs:406
    }
}

// st06bs:316 moveLimit(0,128,280,64) + st06bs:373 moveRand(60,4,1.9).
// Limits x[-140,140], y[96,160]; direction inner zone x+-70, y[112,144].
// Per-frame armed displacement follows transcribe/th16/movement.md; slots int1, fx4, fx5.
sub move_rand_arm() {
    var k: int = self_int(1) + 1;
    set_self_int(1, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx / 60) * 1.9fx; }
    var nx: fx = $self_x + self_fx(4) * speed;
    var ny: fx = $self_y + self_fx(5) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_begin() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(4, cos(a as angle));
    set_self_fx(5, sin(a as angle));
    set_self_int(1, 0);
    move_rand_arm();
}

sub move_rand_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        move_rand_arm();
    }
}

async sub boss3_attack() {
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);  // st06bs:341 movePosTime(60,4,0,128)
    wait(30);                                // st06bs:344
    wait(50);                                // st06bs:347
    wait(60);                                // st06bs:353
    set_self_fx(0, 0.017453fx);              // st06bs:354 F0
    set_self_int(0, 5);                      // st06bs:355 I0
    loop {                                   // st06bs:357-376
        var count: int = 90;
        if global(GVAR_RANK) == RANK_EASY { count = 50; }          // st06bs:358-359
        else if global(GVAR_RANK) == RANK_NORMAL { count = 72; }   // st06bs:360-361
        else if global(GVAR_RANK) == RANK_HARD { count = 80; }     // st06bs:362-363
        boss3_at(self_int(0), count);                              // st06bs:367
        if self_int(0) < 10 { set_self_int(0, self_int(0) + 1); }   // st06bs:368-369
        set_self_fx(0, 0fx - self_fx(0));                          // st06bs:371
        wait(120);                                                 // st06bs:372
        move_rand_begin();                                         // st06bs:373
        move_rand_wait(60);                                        // st06bs:374
    }
}

async sub boss3_main() {
    set_invuln(65535);
    set_hurtbox(28fx);     // Boss entry st06bs:27 setHurtbox(56,56)
    set_hitbox(25fx);      // Boss entry st06bs:28 setHitbox(50,50)
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // st06bs:306 etCancel(640); no bullets yet
    wait(4);                                       // st06bs:311/313: entry time 0 -> 4
    phase_begin(0, boss3_attack, PHASE_FRAMES, 0); // st06bs:318 timerReset / :339 interrupt 2820
    wait_spell();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 21000, 0, 0, 0, boss3_main);  // st06bs:304 lifeSet(21000)
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(1); }
}
